	return nil
}

func matchesString(c constraint, v string) bool {
	value := strings.TrimSpace(c.Value)
	v = strings.TrimSpace(v)
	switch strings.ToLower(strings.TrimSpace(c.Operator)) {
	case opEQ:
		return value == v
	case opNEQ:
		return value != v
	case opEmpty:
		return len(strings.TrimSpace(v)) == 0
	case opNotEmpty, opPresent:
		return len(v) != 0
	case opNotPresent:
		return len(v) == 0
	case opPrefix:
		return strings.HasPrefix(strings.TrimSpace(v), value)
	case opSuffix:
		return strings.HasSuffix(strings.TrimSpace(v), value)
	}
	return false
}

