	"testing"
)

func TestEvaluationStringComparisonTrimsAndIgnoresOperatorCase(t *testing.T) {
	// Removing normalization would make both assertions fail.
	assert.True(t, matchesString(constraint{Operator: "EQ", Value: " hello "}, "hello"))
	assert.True(t, matchesString(constraint{Operator: "PREFIX", Value: " he "}, " hello world "))
}

func TestEvaluationBooleanOperatorNeedsNoConstraintValue(t *testing.T) {
	// Requiring a value for TRUE would reject a valid unary comparison.
	require.NoError(t, validate(constraint{Property: "active", Operator: "TRUE"}))
	match, err := matchesBool(constraint{Operator: "TRUE"}, "true")
	require.NoError(t, err)
	assert.True(t, match)
}

func TestEvaluationBucketAtCutoffSelectsFirstVariant(t *testing.T) {
	// CRC32("flag543") modulo 1000 is 333.
	selected, d := evaluate(&flipt.EvaluationRequest{FlagKey: "flag", EntityId: "543"}, []distribution{{VariantKey: "first"}, {VariantKey: "second"}}, []int{333, 1000})
	assert.True(t, selected)
	assert.Equal(t, "first", d.VariantKey)
}

func TestEvaluatorSelectsLowestRankMatchingRule(t *testing.T) {
	ctx := context.Background()
	flag, err := flagStore.CreateFlag(ctx, &flipt.CreateFlagRequest{Key: t.Name(), Name: t.Name(), Enabled: true})
	require.NoError(t, err)
	low, err := segmentStore.CreateSegment(ctx, &flipt.CreateSegmentRequest{Key: t.Name() + "low", Name: "low"})
	require.NoError(t, err)
	high, err := segmentStore.CreateSegment(ctx, &flipt.CreateSegmentRequest{Key: t.Name() + "high", Name: "high"})
	require.NoError(t, err)
	_, err = ruleStore.CreateRule(ctx, &flipt.CreateRuleRequest{FlagKey: flag.Key, SegmentKey: high.Key, Rank: 2})
	require.NoError(t, err)
	_, err = ruleStore.CreateRule(ctx, &flipt.CreateRuleRequest{FlagKey: flag.Key, SegmentKey: low.Key, Rank: 1})
	require.NoError(t, err)
	for i := 0; i < 20; i++ {
		resp, err := evaluator.Evaluate(ctx, &flipt.EvaluationRequest{FlagKey: flag.Key, EntityId: "entity"})
		require.NoError(t, err)
		assert.True(t, resp.Match)
		assert.Equal(t, low.Key, resp.SegmentKey)
	}
}

func TestStringPresentConstraintCanBeCreatedWithoutValue(t *testing.T) {
	ctx := context.Background()
	segment, err := segmentStore.CreateSegment(ctx, &flipt.CreateSegmentRequest{Key: t.Name(), Name: t.Name()})
	require.NoError(t, err)
	c, err := segmentStore.CreateConstraint(ctx, &flipt.CreateConstraintRequest{SegmentKey: segment.Key, Type: flipt.ComparisonType_STRING_COMPARISON_TYPE, Property: "name", Operator: "PRESENT"})
	require.NoError(t, err)
	assert.Equal(t, "present", c.Operator)
	assert.Empty(t, c.Value)
}

func TestEvaluatorGeneratesRequestIDForDirectCall(t *testing.T) {
	ctx := context.Background()
	flag, err := flagStore.CreateFlag(ctx, &flipt.CreateFlagRequest{Key: t.Name(), Name: t.Name(), Enabled: true})
	require.NoError(t, err)
	resp, err := evaluator.Evaluate(ctx, &flipt.EvaluationRequest{FlagKey: flag.Key, EntityId: "entity", Context: map[string]string{"region": "east"}})
	require.NoError(t, err)
	_, err = uuid.FromString(resp.RequestId)
	require.NoError(t, err)
	assert.Equal(t, map[string]string{"region": "east"}, resp.RequestContext)
	require.NotNil(t, resp.Timestamp)
}
